            case GGML_ET_UBERKERNEL_KERNEL_MUL_MAT_Q4_0:
                {
                    struct ggml_et_binary_params * p = (struct ggml_et_binary_params *) inst_params;

rc                               = mul_mat_Q4_0_entry(p, env);
                    break;
                }

            default:
                return -1;
        }

        if (rc != 0) {
            return rc;
        }
    }

    return 0;
}

